create table public.admin_members(user_id uuid primary key references auth.users(id) on delete cascade);
alter table public.admin_members enable row level security;
revoke all on public.admin_members from anon,authenticated;
grant select on public.admin_members to authenticated;
create policy "Read own admin membership" on public.admin_members for select to authenticated using(user_id=(select auth.uid()));
alter table public.products alter column id add generated by default as identity;
select setval(pg_get_serial_sequence('public.products','id'),greatest(coalesce((select max(id) from public.products),0),1));
alter table public.products add column description text not null default '', add column stock integer not null default 0 check(stock>=0), add column sku text unique, add column image_url text not null default '', add column compare_price integer check(compare_price is null or compare_price>=0);
grant insert,update,delete on public.products to authenticated;
grant usage,select on sequence public.products_id_seq to authenticated;
create policy "Admins manage catalog" on public.products for all to authenticated using(exists(select 1 from public.admin_members where user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_members where user_id=(select auth.uid())));
create table public.store_settings(id integer primary key check(id=1), announcement text not null default 'A little luxury, every day.', delivery_fee integer not null default 80 check(delivery_fee>=0), support_email text not null default '');
insert into public.store_settings(id) values(1);
alter table public.store_settings enable row level security;
revoke all on public.store_settings from anon,authenticated;
grant select on public.store_settings to anon,authenticated;
grant update on public.store_settings to authenticated;
create policy "Read store settings" on public.store_settings for select to anon,authenticated using(true);
create policy "Admins update settings" on public.store_settings for update to authenticated using(exists(select 1 from public.admin_members where user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_members where user_id=(select auth.uid())));
create table public.orders(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),customer_name text not null,phone text not null,address text not null,items_note text not null,total integer not null check(total>=0),status text not null default 'pending' check(status in ('pending','confirmed','packed','shipped','delivered','cancelled')),payment_status text not null default 'unpaid' check(payment_status in ('unpaid','paid','refunded')),tracking_number text not null default '',admin_note text not null default '');
alter table public.orders enable row level security;
revoke all on public.orders from anon,authenticated;
grant select,insert,update on public.orders to authenticated;
create policy "Admins manage orders" on public.orders for all to authenticated using(exists(select 1 from public.admin_members where user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_members where user_id=(select auth.uid())));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']);
create policy "Admins upload product images" on storage.objects for insert to authenticated with check(bucket_id='product-images' and exists(select 1 from public.admin_members where user_id=(select auth.uid())));
create policy "Admins view product images" on storage.objects for select to authenticated using(bucket_id='product-images' and exists(select 1 from public.admin_members where user_id=(select auth.uid())));
create policy "Admins remove product images" on storage.objects for delete to authenticated using(bucket_id='product-images' and exists(select 1 from public.admin_members where user_id=(select auth.uid())));
